<?php require_once 'app.php'; require_admin();$users=db()->query('SELECT id,nome,email,perfil,ativo,criado_em FROM usuarios ORDER BY nome')->fetchAll();layout_start('Administração');?><div class="d-flex justify-content-between mb-3"><p class="text-muted">Gerencie os acessos ao sistema.</p><a class="btn btn-primary" href="adicionar_usuario.php">Novo usuário</a></div><div class="card p-3 table-responsive"><table class="table"><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Status</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['nome'])?></td><td><?=e($u['email'])?></td><td><?=e($u['perfil'])?></td><td><?=$u['ativo']?'Ativo':'Inativo'?></td></tr><?php endforeach;?></table></div><?php layout_end();